{
  "date": "2026-10-04",
  "reviewer": "Codex visual inspection; owner decisions pending",
  "scope": "train only; purposive selection, not a measured label error rate",
  "reviewed_unique_images": 18,
  "viewing_method": "R01-R06 via class contact sheets; R07-R16 and W01-W02 at full overlay size",
  "prior_24_overlays": "generated previously; not all claimed visually reviewed",
  "observations": [
    {
      "id": "R01",
      "overlay": "outputs/roboflow-v1-20261004-complete-v2/review/0001.png",
      "observation": "Box nhỏ nhất chỉ 1x4 pixel; nhiều box ID0 quanh mặt/đầu; có người không có box.",
      "owner_question": "Box quá nhỏ có bằng chứng để giữ hay cần ignore/relabel?"
    },
    {
      "id": "R02",
      "overlay": "outputs/roboflow-v1-20261004-complete-v2/review/0002.png",
      "observation": "ID0 trên nhiều tư thế, gồm người nhìn xuống và nhìn ngang.",
      "owner_question": "Định nghĩa looking_around có khớp những tư thế này không?"
    },
    {
      "id": "R03",
      "overlay": "outputs/roboflow-v1-20261004-complete-v2/review/0003.png",
      "observation": "ID0 bao gần toàn ảnh cận cảnh; ảnh có nhiễu chấm; người cầm vật giống điện thoại.",
      "owner_question": "Xác nhận hành vi nguồn và nhãn còn thiếu; không map tự động."
    },
    {
      "id": "R04",
      "overlay": "outputs/roboflow-v1-20261004-complete-v2/review/0004.png",
      "observation": "Cảnh thi nhiều người; ID1 nhỏ quanh đầu, các ID0 có kích thước/unit khác.",
      "owner_question": "ID1 có thể dùng làm negative đã review không? Chưa có đủ bằng chứng."
    },
    {
      "id": "R05",
      "overlay": "outputs/roboflow-v1-20261004-complete-v2/review/0005.png",
      "observation": "ID1 trên nhiều người, gồm người gục trên bàn; có watermark Alamy.",
      "owner_question": "Phạm vi normal và nguồn/quyền asset này cần đối chiếu thế nào?"
    },
    {
      "id": "R06",
      "overlay": "outputs/roboflow-v1-20261004-complete-v2/review/0006.png",
      "observation": "ID1 có box phủ toàn ảnh và box phủ người phía trước.",
      "owner_question": "Box toàn ảnh gồm nhiều người có phù hợp person unit không?"
    },
    {
      "id": "R07",
      "overlay": "outputs/roboflow-v1-20261004-complete-v2/review/0007.png",
      "observation": "ID2 nhỏ nhất 15x7 pixel tại vùng bàn/tay, không phải cả người.",
      "owner_question": "Không nhìn đủ rõ để xác nhận phone; giữ, ignore hay annotate lại?"
    },
    {
      "id": "R08",
      "overlay": "outputs/roboflow-v1-20261004-complete-v2/review/0008.png",
      "observation": "ID2 bao thân trên của hai người đang cầm vật giống điện thoại.",
      "owner_question": "Chốt annotation unit người hay điện thoại?"
    },
    {
      "id": "R09",
      "overlay": "outputs/roboflow-v1-20261004-complete-v2/review/0009.png",
      "observation": "Cùng ID2: một box bao người/gần cả ảnh, box khác bao tay và điện thoại; ảnh có nhiễu chấm.",
      "owner_question": "Hai box cùng nhãn nhưng khác unit: cần relabel thống nhất trước dùng."
    },
    {
      "id": "R10",
      "overlay": "outputs/roboflow-v1-20261004-complete-v2/review/0010.png",
      "observation": "Người cầm điện thoại trong cảnh nói chuyện trước camera; ID2 bao người.",
      "owner_question": "Có giữ ảnh ngoài domain phòng thi trong tập bổ sung không?"
    },
    {
      "id": "R11",
      "overlay": "outputs/roboflow-v1-20261004-complete-v2/review/0011.png",
      "observation": "Ảnh chụp màn hình web/video với UI; ID2 bao người cúi đầu, phone khó xác minh.",
      "owner_question": "Cần bằng chứng phone rõ hơn; không suy từ tư thế cúi đầu."
    },
    {
      "id": "R12",
      "overlay": "outputs/roboflow-v1-20261004-complete-v2/review/0012.png",
      "observation": "ID2 bao tay/điện thoại dưới bàn; có vật giống phone trên bàn khác không có box.",
      "owner_question": "Định nghĩa tương tác/cầm khác phone chỉ nằm trên bàn; kiểm completeness theo guideline."
    },
    {
      "id": "R13",
      "overlay": "outputs/roboflow-v1-20261004-complete-v2/review/0013.png",
      "observation": "ID2 nhỏ quanh vùng tay phía sau; ID0 quanh đầu/người phía trước.",
      "owner_question": "Có đủ bằng chứng thị giác cho từng box, có cần ignore khi che khuất?"
    },
    {
      "id": "R14",
      "overlay": "outputs/roboflow-v1-20261004-complete-v2/review/0014.png",
      "observation": "Góc nhìn từ trên xuống; ID2 bao tay/thiết bị cạnh laptop.",
      "owner_question": "Unit và góc camera có phù hợp subset person-behavior không?"
    },
    {
      "id": "R15",
      "overlay": "outputs/roboflow-v1-20261004-complete-v2/review/0015.png",
      "observation": "ID2 bao thân người nhìn/cầm điện thoại; ảnh có nhiễu chấm.",
      "owner_question": "Cần xác minh nguồn ảnh/nhiễu; không suy xuất xứ augmentation từ ảnh."
    },
    {
      "id": "R16",
      "overlay": "outputs/roboflow-v1-20261004-complete-v2/review/0016.png",
      "observation": "ID2 bao người cầm phone; có phụ đề trong ảnh.",
      "owner_question": "Giữ hay loại UI/phụ đề/domain khác khi thiết kế subset?"
    },
    {
      "id": "W01",
      "overlay": "outputs/roboflow-v1-20261004-complete-v2/review/warning-1.png",
      "observation": "BBox đỏ vượt biên rất nhỏ; người phía trước cầm phone nhưng được ID0.",
      "owner_question": "Tách sửa geometry khỏi kiểm nhãn sai/thiếu phone; không sửa tự động."
    },
    {
      "id": "W02",
      "overlay": "outputs/roboflow-v1-20261004-complete-v2/review/warning-2.png",
      "observation": "BBox đỏ chạm cạnh phải, mức vượt chỉ khoảng 0.005 pixel.",
      "owner_question": "Owner quyết định rule xử lý subpixel ở version mới; validator hiện giữ nguyên."
    }
  ]
}
